from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    separated_groups = []  # Step 2: Initialize an empty list to store separated groups

    start = 0
    for i in range(len(paren_string)):
        if paren_string[i] == '(':
            count = 1
            for j in range(i + 1, len(paren_string)):
                if paren_string[j] == '(':
                    count += 1
                elif paren_string[j] == ')':
                    count -= 1
                if count == 0:
                    separated_groups.append(paren_string[i:j + 1])  # Step 4: Separate each group into individual strings
                    break

    return separated_groups  # Step 6: Return the list of separated groups

